using System;
using System.Linq;
using UnityEngine;
using UnityEditor;
public static class ValidateVehicleEquipment {
public static string Main(){if(!Application.isPlaying)throw new Exception("Requires Play");var original=UnityEngine.Object.FindAnyObjectByType<VehiclePhysics>();var originalBody=original.GetComponent<Rigidbody>();bool wasKinematic=originalBody.isKinematic;var originalVelocity=originalBody.linearVelocity;var originalAngular=originalBody.angularVelocity;var mode=Physics.simulationMode;bool paused=EditorApplication.isPaused;GameObject clone=null,fixture=null,tree=null,wall=null;string result="";try{Physics.simulationMode=SimulationMode.Script;EditorApplication.isPaused=true;originalBody.isKinematic=true;clone=UnityEngine.Object.Instantiate(original.gameObject,new Vector3(20000,20.65f,20000),Quaternion.identity);clone.name="TEMP equipment validation";var v=clone.GetComponent<VehiclePhysics>();var rb=clone.GetComponent<Rigidbody>();rb.isKinematic=false;v.externalControl=true;v.automaticSimulation=false;clone.GetComponent<VehiclePlayerInput>().enabled=false;clone.GetComponent<VehicleAudio>().enabled=false;v.Initialize();if(v.FourWheelDrive)throw new Exception("AWD must default OFF");var config=v.profile.equipment;if(config.driveKey!=UnityEngine.InputSystem.Key.H||config.chainsKey!=UnityEngine.InputSystem.Key.Digit1||config.winchKey!=UnityEngine.InputSystem.Key.Digit2)throw new Exception("Wrong default controls");fixture=GameObject.CreatePrimitive(PrimitiveType.Cube);fixture.transform.position=new Vector3(20000,19.5f,20000);fixture.transform.localScale=new Vector3(100,1,100);Physics.SyncTransforms();Action step=()=>{v.Simulate(.01f);Physics.Simulate(.01f);v.SendMessage("LateUpdate");};v.SetInput(new VehicleControlInput{brake=1});for(int i=0;i<200;i++)step();v.SetInput(new VehicleControlInput{handbrake=true});rb.linearVelocity=Vector3.zero;rb.angularVelocity=Vector3.zero;var chains=clone.GetComponent<TruckChains>();if(!chains.RequestToggle())throw new Exception("Chain fitting rejected");chains.Advance(config.installationSeconds+.1f);if(!chains.Installed||chains.wheelChainVisuals.Length!=v.Wheels.Length||chains.wheelChainVisuals.Any(x=>!x.activeSelf))throw new Exception("Not all wheels chained");v.SetInput(default);step();if(v.Wheels.Any(w=>w.forwardFriction.stiffness<.6f))throw new Exception("Front/rear chain grip missing: "+string.Join(";",v.Wheels.Select(w=>"ground="+w.isGrounded+" mu="+w.forwardFriction.stiffness+" p="+w.transform.position))+" installed="+chains.Installed+" bonus="+v.profile.baseSoilChainedLongitudinal+" flags="+string.Join(",",v.profile.axles.Select(a=>a.chains)));chains.AdvanceCondition(4,8);float worn=chains.Integrity,hot=chains.TemperatureC;if(worn>=1||hot<=config.ambientTemperatureC)throw new Exception("No chain wear/heating");rb.linearVelocity=Vector3.zero;rb.angularVelocity=Vector3.zero;v.SetInput(new VehicleControlInput{handbrake=true});if(!chains.RequestToggle())throw new Exception("Cannot remove chains");chains.Advance(config.installationSeconds+.1f);chains.AdvanceCondition(20,0);if(chains.TemperatureC>=hot||Mathf.Abs(chains.Integrity-worn)>.0001f)throw new Exception("Cooling repairs wear or fails");if(!chains.RequestToggle())throw new Exception("Cannot refit");chains.Advance(config.installationSeconds+.1f);if(Mathf.Abs(chains.Integrity-worn)>.0001f)throw new Exception("Refitting resets wear");for(int i=0;i<3000&&!chains.Broken;i++)chains.AdvanceCondition(.01f,30);if(!chains.Broken||chains.Installed||chains.GripFactor!=0||chains.wheelChainVisuals.Any(x=>x.activeSelf)||chains.RequestToggle())throw new Exception("Chain break state invalid");result+="default 2WD/keys; all "+v.Wheels.Length+" wheels chained; wear="+(1-worn).ToString("P1")+", heat="+hot.ToString("F1")+"C; cooling/no refit repair; overheat break removes visuals/grip; ";
var winch=clone.GetComponent<VehicleWinch>();v.SetInput(default);v.SetNeutral(true);tree=GameObject.CreatePrimitive(PrimitiveType.Cube);tree.name="TEMP actual fixed anchor";tree.transform.position=winch.Mount+Vector3.forward*12;tree.transform.localScale=new Vector3(.5f,2,.5f);tree.AddComponent<WinchAnchorSurface>();Physics.SyncTransforms();var anchor=tree.GetComponent<Collider>();if(!winch.Attach(anchor,anchor.ClosestPoint(winch.Mount)))throw new Exception("Valid anchor rejected: "+winch.Message);var begin=rb.position;float maxTension=0;for(int i=0;i<600;i++){step();maxTension=Mathf.Max(maxTension,winch.TensionNewtons);}float moved=rb.position.z-begin.z;if(moved<1||maxTension<=0||maxTension>config.maximumPullNewtons+.1f)throw new Exception("Winch no physical pull moved="+moved+" N="+maxTension);wall=GameObject.CreatePrimitive(PrimitiveType.Cube);wall.transform.position=(winch.Mount+anchor.ClosestPoint(winch.Mount))*.5f;wall.transform.localScale=new Vector3(3,3,.5f);Physics.SyncTransforms();winch.Simulate(.01f);if(winch.Pulling||winch.TensionNewtons!=0)throw new Exception("Winch pulls through obstacle");UnityEngine.Object.DestroyImmediate(wall);wall=null;Physics.SyncTransforms();if(!winch.Attach(anchor,anchor.ClosestPoint(winch.Mount)))throw new Exception("Reattach failed");winch.AdvanceWear(config.maximumContinuousPullSeconds+1,1);if(!winch.Broken||winch.Pulling||winch.TensionNewtons!=0||winch.Attach(anchor,anchor.ClosestPoint(winch.Mount)))throw new Exception("Cable break is bypassable");result+="winch physical travel="+moved.ToString("F2")+"m / 6s, peak="+(maxTension/1000).ToString("F1")+"kN, obstacle stops force, continuous pull breaks cable and cannot reattach.";return "PASS VEHICLE EQUIPMENT: "+result;
}finally{foreach(var go in new[]{clone,fixture,tree,wall})if(go!=null)UnityEngine.Object.DestroyImmediate(go);originalBody.isKinematic=wasKinematic;if(!wasKinematic){originalBody.linearVelocity=originalVelocity;originalBody.angularVelocity=originalAngular;}Physics.simulationMode=mode;EditorApplication.isPaused=paused;}}
}


